'use strict';
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let started=false,dirty=false,loading=false,aiReady=false,imageTarget=null,toastTimer,meta={name:'Untitled website',brief:'',kind:'new'},suggestionRun=0;
const BASE_CSS='*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:#18382b;background:#fff;font-size:16px;line-height:1.6}img{max-width:100%;height:auto}h1,h2,h3,p,a{overflow-wrap:anywhere}.oak-columns{display:flex;gap:24px;align-items:stretch;flex-wrap:wrap}.oak-column{flex:1 1 240px;min-width:0}@media(max-width:600px){.oak-columns{flex-direction:column}}';
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4500);}
function markDirty(){if(loading||!started)return;dirty=true;$('save-status').textContent='Unsaved changes · save an editable project';}
function switchTab(id,focus=false){document.querySelectorAll('[data-tab]').forEach(button=>{const active=button.dataset.tab===id;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;$(button.getAttribute('aria-controls')).hidden=!active;if(active&&focus)button.focus();});}
document.querySelectorAll('[data-tab]').forEach((button,i,buttons)=>{button.addEventListener('click',()=>switchTab(button.dataset.tab));button.addEventListener('keydown',e=>{let index;if(e.key==='ArrowRight')index=(i+1)%buttons.length;if(e.key==='ArrowLeft')index=(i+buttons.length-1)%buttons.length;if(e.key==='Home')index=0;if(e.key==='End')index=buttons.length-1;if(index!==undefined){e.preventDefault();switchTab(buttons[index].dataset.tab,true);}});});
const editor=grapesjs.init({container:'#gjs',height:'100%',width:'auto',storageManager:false,noticeOnUnload:false,panels:{defaults:[]},selectorManager:{componentFirst:true},fromElement:false,components:'',style:BASE_CSS,exportWrapper:true,wrapperIsBody:true,jsInHtml:false,showOffsets:true,deviceManager:{devices:[{name:'Desktop',width:''},{name:'Tablet',width:'768px',widthMedia:'992px'},{name:'Mobile',width:'390px',widthMedia:'600px'}]},layerManager:{appendTo:'#layers'},traitManager:{appendTo:'#traits'},styleManager:{appendTo:'#style-manager',sectors:[{name:'Layout & size',open:true,properties:['display','flex-direction','justify-content','align-items','gap','width','max-width','min-height']},{name:'Spacing',open:false,properties:['padding','margin']},{name:'Typography',open:true,properties:['font-family','font-size','font-weight','line-height','letter-spacing','text-align','color']},{name:'Background & border',open:false,properties:['background-color','border','border-radius','box-shadow','opacity']},{name:'Position',open:false,properties:['position','top','right','bottom','left','z-index']}]},parser:{optionsHtml:{allowScripts:false,allowUnsafeAttr:false,allowUnsafeAttrValue:false}},canvas:{scripts:[],styles:[]},assetManager:{upload:false,assets:[]}});
const col=()=>({tagName:'div',name:'Column',classes:['oak-column'],style:{'min-height':'140px',padding:'20px',border:'1px dashed #b7c2b7'},droppable:true});
const blocks=[
 {id:'section',label:'Section',icon:'▱',make:()=>({tagName:'section',name:'Section',style:{padding:'48px 6%','min-height':'200px'},droppable:true})},
 {id:'container',label:'Container',icon:'□',make:()=>({tagName:'div',name:'Container',style:{'max-width':'1100px',margin:'0 auto',padding:'24px','min-height':'100px'},droppable:true})},
 {id:'heading',label:'Heading',icon:'H',make:()=>({type:'text',tagName:'h1',name:'Heading',content:'Your next great idea',style:{'font-size':'48px','line-height':'1.1','font-weight':'500',margin:'0 0 24px'}})},
 {id:'text',label:'Text',icon:'T',make:()=>({type:'text',tagName:'p',name:'Text',content:'Tell your story, in your own words.',style:{'font-size':'18px','line-height':'1.7',margin:'0 0 24px'}})},
 {id:'image',label:'Image',icon:'▧',make:()=>({type:'image',name:'Image',attributes:{alt:'',src:''},style:{width:'100%','min-height':'140px','object-fit':'cover'},resizable:true})},
 {id:'button',label:'Button',icon:'↗',make:()=>({type:'link',name:'Button',content:'Discover more',attributes:{href:'#'},style:{display:'inline-block',padding:'14px 24px','background-color':'#18382b',color:'#ffffff','border-radius':'7px','text-decoration':'none'}})},
 {id:'columns',label:'2 columns',icon:'Ⅱ',make:()=>({tagName:'div',name:'Two columns',classes:['oak-columns'],style:{padding:'24px'},components:[col(),col()]})},
 {id:'grid',label:'3 columns',icon:'Ⅲ',make:()=>({tagName:'div',name:'Three columns',classes:['oak-columns'],style:{padding:'24px'},components:[col(),col(),col()]})},
 {id:'divider',label:'Divider',icon:'―',make:()=>({tagName:'hr',name:'Divider',style:{border:'none','border-top':'1px solid #bfc7bf',margin:'28px 0'}})},
 {id:'spacer',label:'Space',icon:'↕',make:()=>({tagName:'div',name:'Space',style:{height:'48px'},droppable:false})},
 {id:'list',label:'List',icon:'≡',make:()=>({tagName:'ul',name:'List',components:[{tagName:'li',type:'text',content:'Your first point'},{tagName:'li',type:'text',content:'Your next point'}],style:{'line-height':'1.9'}})},
 {id:'quote',label:'Quote',icon:'“',make:()=>({tagName:'blockquote',type:'text',name:'Quote',content:'A few words worth remembering.',style:{'font-family':'Georgia,serif','font-size':'28px',padding:'24px','border-left':'3px solid #b69b68'}})}
];
function insertBlock(id,into){const block=blocks.find(b=>b.id===id);if(!block)return;const selected=into||editor.getSelected(),tag=selected?.get('tagName');const target=selected&&['section','div','main','header','footer','nav','article','aside','body'].includes(tag)&&selected.get('droppable')!==false?selected:editor.getWrapper();const added=target.append(block.make())[0];editor.select(added);if(id==='image'){imageTarget=added;$('image-file').click();}updateEmpty();markDirty();return added;}
$('blocks').innerHTML=blocks.map(b=>`<button class="block-button" data-block="${b.id}"><span class="icon" aria-hidden="true">${b.icon}</span>${b.label}</button>`).join('');
document.querySelectorAll('[data-block]').forEach(button=>button.addEventListener('click',()=>insertBlock(button.dataset.block)));
$('first-section').addEventListener('click',()=>insertBlock('section'));
$('blank-ai').addEventListener('click',()=>{switchTab('assistant');$('project-brief').focus();});
function updateEmpty(){$('blank-guide').hidden=editor.getWrapper().components().length>0;}
function updateSelection(){const selected=editor.getSelected(),root=editor.getWrapper(),isRoot=!selected||selected===root;const tag=selected?.get('tagName')||'body';$('selected-name').textContent=isRoot?'Page style':selected.getName();$('selected-status').textContent=isRoot?'Page selected':selected.getName()+' selected';['duplicate','remove','select-parent'].forEach(id=>$(id).disabled=isRoot);const textLike=!!selected&&/^(h[1-6]|p|a|button|li|blockquote|span)$/.test(tag)&&!selected.find('img').length;$('text-control').hidden=!textLike;if(textLike){const doc=new DOMParser().parseFromString(selected.toHTML(),'text/html');$('element-text').value=doc.body.textContent||'';}$('link-control').hidden=tag!=='a';if(tag==='a')$('element-link').value=selected.getAttributes().href||'';$('image-control').hidden=tag!=='img';if(tag==='img')$('image-alt').value=selected.getAttributes().alt||'';}
editor.on('load',()=>{editor.select(editor.getWrapper());updateEmpty();});editor.on('component:selected component:deselected',updateSelection);editor.on('update',()=>{updateEmpty();markDirty();$('undo').disabled=!editor.UndoManager.hasUndo();$('redo').disabled=!editor.UndoManager.hasRedo();});
$('undo').addEventListener('click',()=>{editor.UndoManager.undo();updateEmpty();});$('redo').addEventListener('click',()=>{editor.UndoManager.redo();updateEmpty();});
$('page-style').addEventListener('click',()=>editor.select(editor.getWrapper()));$('select-parent').addEventListener('click',()=>{const parent=editor.getSelected()?.parent();if(parent)editor.select(parent);});
$('duplicate').addEventListener('click',()=>{const selected=editor.getSelected();if(!selected||selected===editor.getWrapper())return;const copy=selected.clone();selected.parent().append(copy,{at:selected.index()+1});editor.select(copy);});
$('remove').addEventListener('click',()=>{const selected=editor.getSelected();if(selected&&selected!==editor.getWrapper())selected.remove();});
$('apply-text').addEventListener('click',()=>{const selected=editor.getSelected();if(selected){selected.components(esc($('element-text').value).replace(/\n/g,'<br>'));markDirty();}});
function safeLink(value){return /^(https?:\/\/|mailto:|tel:|#)/i.test(value)||value==='';}
$('apply-link').addEventListener('click',()=>{const value=$('element-link').value.trim();if(!safeLink(value)){toast('Use an https://, mailto:, tel: or #section link.');return;}editor.getSelected()?.addAttributes({href:value||'#'});markDirty();});
$('image-alt').addEventListener('input',()=>{editor.getSelected()?.addAttributes({alt:$('image-alt').value});markDirty();});
$('replace-image').addEventListener('click',()=>{imageTarget=editor.getSelected();$('image-file').click();});
editor.on('asset:custom',()=>{});
editor.on('run:open-assets',()=>{editor.stopCommand('open-assets');imageTarget=editor.getSelected();$('image-file').click();});
$('image-file').addEventListener('change',async event=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024){toast('Choose a PNG, JPG or WebP image under 5 MB.');return;}try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});await new Promise((resolve,reject)=>{const image=new Image();image.onload=resolve;image.onerror=reject;image.src=data;});if(imageTarget&&imageTarget.parent()){imageTarget.addAttributes({src:data});editor.select(imageTarget);markDirty();toast('Image added to your website.');}}catch{toast('That image could not be opened.');}});
document.querySelectorAll('[data-device]').forEach(button=>button.addEventListener('click',()=>{editor.setDevice(button.dataset.device);document.querySelectorAll('[data-device]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));}));
document.querySelectorAll('dialog .dialog-close').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
$('start-dialog').addEventListener('cancel',e=>{if(!started)e.preventDefault();});
function showStart(kind='new'){document.querySelector(`[name="project-kind"][value="${kind}"]`).checked=true;$('close-start').hidden=!started;$('start-name').value='';$('start-brief').value='';$('start-file').value='';$('start-error').textContent='';updateStartMode();$('start-dialog').showModal();}
function updateStartMode(){const existing=document.querySelector('[name="project-kind"]:checked').value==='existing';$('existing-options').hidden=!existing;$('aim-label').textContent=existing?'What would you like to change?':'What do you want to make?';$('start-submit').innerHTML=existing?'Open my website <span>↗</span>':'Open my canvas <span>↗</span>';}
document.querySelectorAll('[name="project-kind"]').forEach(input=>input.addEventListener('change',updateStartMode));
$('new-project').addEventListener('click',()=>showStart());$('open-project').addEventListener('click',()=>showStart('existing'));
function cleanCss(css){return String(css||'').replace(/@import\s[\s\S]*?;/gi,'').replace(/url\(\s*(['"]?)(?!data:image\/(?:png|jpeg|webp);base64,)[\s\S]*?\1\s*\)/gi,'none').replace(/<\/?style/gi,'').replace(/expression\s*\(/gi,'blocked(').replace(/-moz-binding\s*:/gi,'blocked:');}
function cleanDocument(source,extraCss=''){
 const doc=new DOMParser().parseFromString(source,'text/html');const css=cleanCss([...doc.querySelectorAll('style')].map(s=>s.textContent).join('\n')+'\n'+extraCss);const bodyStyle=cleanCss(doc.body.getAttribute('style')||''),bodyId=doc.body.getAttribute('id')||'',bodyClass=doc.body.getAttribute('class')||'';
 doc.querySelectorAll('script,style,link,meta,base,iframe,object,embed,form,input,textarea,select,video,audio,source').forEach(el=>el.remove());
 const clean=DOMPurify.sanitize(doc.body.innerHTML,{USE_PROFILES:{html:true},ALLOW_DATA_ATTR:false,FORBID_TAGS:['script','iframe','object','embed','form','input','textarea','select','style','link','meta','base'],FORBID_ATTR:['srcset','srcdoc','formaction','action','ping']});
 const safe=new DOMParser().parseFromString(clean,'text/html');safe.querySelectorAll('*').forEach(el=>{for(const attr of [...el.attributes]){if(attr.name.startsWith('data-gjs-')||attr.name.startsWith('on'))el.removeAttribute(attr.name);}if(el.hasAttribute('style'))el.setAttribute('style',cleanCss(el.getAttribute('style')));if(el.hasAttribute('href')&&!safeLink(el.getAttribute('href')))el.removeAttribute('href');if(el.hasAttribute('src')&&!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(el.getAttribute('src')))el.removeAttribute('src');if(el.tagName==='A'&&el.getAttribute('target')==='_blank')el.setAttribute('rel','noopener noreferrer');});
 return {html:safe.body.innerHTML,css,body:{...(bodyId?{id:bodyId}:{}),...(bodyClass?{class:bodyClass}:{}),...(bodyStyle?{style:bodyStyle}:{})},title:(doc.title||'').slice(0,80)};
}
function loadContent(content,{resetHistory=false}={}){loading=true;editor.setComponents(content.html);editor.setStyle(BASE_CSS+'\n'+content.css);editor.getWrapper().setAttributes(content.body||{});if(content.body?.style){const declaration=document.createElement('div');declaration.setAttribute('style',content.body.style);const values={};for(const property of declaration.style)values[property]=declaration.style.getPropertyValue(property);editor.getWrapper().setStyle(values);}else editor.getWrapper().setStyle({});if(resetHistory)editor.UndoManager.clear();loading=false;updateEmpty();editor.select(editor.getWrapper());}
function legacyProject(model){if(!model||typeof model!=='object')throw new Error('Invalid project');const text=v=>typeof v==='string'?esc(v.slice(0,5000)):'';const parts=[`<section style="padding:60px 8%"><h1>${text(model.headline).replace(/\n/g,'<br>')}</h1><p>${text(model.description)}</p></section>`];if(Array.isArray(model.services))parts.push(`<section style="padding:40px 8%">${model.services.slice(0,20).map(s=>`<article><h2>${text(s.title)}</h2><p>${text(s.text)}</p></article>`).join('')}</section>`);if(model.aboutText)parts.push(`<section style="padding:40px 8%"><h2>${text(model.aboutTitle)}</h2><p>${text(model.aboutText)}</p></section>`);if(Array.isArray(model.faqs))parts.push(`<section style="padding:40px 8%">${model.faqs.slice(0,20).map(s=>`<details><summary>${text(s.q)}</summary><p>${text(s.a)}</p></details>`).join('')}</section>`);if(typeof model.image==='string'&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(model.image))parts.splice(1,0,`<img src="${model.image}" alt="">`);return cleanDocument(parts.join(''));}
async function readProject(file){if(!file)throw new Error('Choose an HTML website or an Oakline project file.');if(file.size>15*1024*1024)throw new Error('Choose a project smaller than 15 MB.');const text=await file.text();if(/\.json$/i.test(file.name)){let root;try{root=JSON.parse(text);}catch{throw new Error('This JSON file could not be read.');}if(root.format==='oakline-canvas-project'&&root.version===2&&typeof root.html==='string'&&typeof root.css==='string'){if(root.html.length+root.css.length>14*1024*1024)throw new Error('Project content is too large.');return{content:cleanDocument(root.html,root.css),name:typeof root.name==='string'?root.name.slice(0,80):'',brief:typeof root.brief==='string'?root.brief.slice(0,4000):''};}if(root.format==='oakline-studio-project'&&root.schemaVersion===1)return{content:legacyProject(root.project),name:String(root.project.brand||'Imported website').slice(0,80),brief:'',legacy:true};throw new Error('Choose an Oakline project file, or import an HTML website.');}if(!/\.(html?|htm)$/i.test(file.name))throw new Error('Choose an HTML or Oakline JSON file.');return{content:cleanDocument(text),name:'',brief:''};}
$('start-form').addEventListener('submit',async event=>{event.preventDefault();$('start-error').textContent='';const kind=document.querySelector('[name="project-kind"]:checked').value;try{const imported=kind==='existing'?await readProject($('start-file').files[0]):null;if(started&&dirty&&!confirm('Open a different website? Download an editable project first if you want to keep your current work.'))return;meta={name:$('start-name').value.trim()||imported?.name||imported?.content.title||'Untitled website',brief:$('start-brief').value.trim()||imported?.brief||'',kind};loading=true;loadContent(imported?.content||{html:'',css:'',body:{}},{resetHistory:true});$('project-name').value=meta.name;$('project-brief').value=meta.brief;$('project-mode').textContent=kind==='new'?'NEW WEBSITE':'EDITING WEBSITE';$('ai-results').replaceChildren();suggestionRun++;started=true;loading=false;dirty=false;$('save-status').textContent='Not saved · save an editable project to keep your work';$('start-dialog').close();switchTab('add');toast(imported?.legacy?'Previous project content imported into the new canvas.':kind==='existing'?'Website opened. Your original file is unchanged.':'Your canvas is ready. Start with any element.');}catch(error){$('start-error').textContent=error.message;}});
$('project-name').addEventListener('input',()=>{meta.name=$('project-name').value.trim()||'Untitled website';markDirty();});$('project-brief').addEventListener('input',()=>{meta.brief=$('project-brief').value;markDirty();});$('edit-brief').addEventListener('click',()=>{switchTab('assistant');$('project-brief').focus();});
$('edit-code').addEventListener('click',()=>{$('code-html').value=editor.getHtml();$('code-css').value=editor.getCss();$('code-error').textContent='';$('code-dialog').showModal();});$('apply-code').addEventListener('click',()=>{try{if($('code-html').value.length+$('code-css').value.length>14*1024*1024)throw new Error('Keep the page under 14 MB.');loadContent(cleanDocument($('code-html').value,$('code-css').value));markDirty();$('code-dialog').close();toast('Your HTML and CSS are on the canvas.');}catch(error){$('code-error').textContent=error.message;}});
function exportHtml(){const content=cleanDocument(editor.getHtml(),editor.getCss());const attrs=Object.entries(content.body).map(([key,value])=>` ${key}="${esc(value)}"`).join('');return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(meta.name)}</title><style>${BASE_CSS}\n${content.css}</style></head><body${attrs}>${content.html}</body></html>`;}
function slug(){return meta.name.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,70)||'my-website';}
function download(contents,type,name){const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
$('download').addEventListener('click',()=>$('export-dialog').showModal());$('export-html').addEventListener('click',()=>{download(exportHtml(),'text/html;charset=utf-8',slug()+'.html');toast('Your website download has started.');});$('export-project').addEventListener('click',()=>{const data={format:'oakline-canvas-project',version:2,name:meta.name,brief:meta.brief,html:editor.getHtml(),css:editor.getCss()};const file=JSON.stringify(data,null,2);if(new Blob([file]).size>15*1024*1024){toast('This project exceeds the 15 MB import limit. Remove or resize large images before saving.');return;}download(file,'application/json',slug()+'.oakline.json');dirty=false;$('save-status').textContent='Editable project downloaded';toast('Keep your project file to reopen this design.');});
$('preview').addEventListener('click',()=>{$('preview-title').textContent=meta.name;$('preview-frame').srcdoc=exportHtml();$('preview-dialog').showModal();});$('preview-dialog').addEventListener('close',()=>$('preview-frame').srcdoc='');$('help').addEventListener('click',()=>$('help-dialog').showModal());
async function checkAI(){try{const response=await fetch('/api/assistant/status',{cache:'no-store'});if(!response.ok)throw new Error();const data=await response.json();aiReady=data.available===true;$('ai-status').textContent=aiReady?'Ready when you are. Suggestions only change your page when you choose to apply them.':'AI suggestions are not connected yet. You can use every design tool while the site owner connects the assistant.';}catch{$('ai-status').textContent='AI suggestions are not connected yet. Your design tools are ready to use.';}finally{$('ask-ai').disabled=!aiReady;}}
$('ask-ai').addEventListener('click',async()=>{if(!aiReady)return;const brief=$('project-brief').value.trim(),prompt=$('ai-prompt').value.trim();if(!brief&&!prompt){$('ai-status').textContent='Describe your website or ask a design question first.';$('project-brief').focus();return;}const run=++suggestionRun;$('ask-ai').disabled=true;$('ai-status').textContent='Thinking through a few directions…';try{const doc=new DOMParser().parseFromString(editor.getHtml(),'text/html');const outline=[...doc.querySelectorAll('h1,h2,h3,p')].map(el=>el.tagName+': '+el.textContent).join('\n').slice(0,4000);const response=await fetch('/api/assistant/suggest',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({brief,prompt,outline}),signal:AbortSignal.timeout(40000)});const result=await response.json();if(!response.ok)throw new Error(result.error||'The assistant could not reply. Please try again.');if(run!==suggestionRun)return;renderSuggestions(result);$('ai-status').textContent='Here are some directions to explore. Your canvas is unchanged.';}catch(error){if(run===suggestionRun)$('ai-status').textContent=error.name==='TimeoutError'?'The assistant took too long. Please try again.':error.message;}finally{$('ask-ai').disabled=!aiReady;}});
function renderSuggestions(result){const area=$('ai-results');area.replaceChildren();if(!Array.isArray(result.suggestions))throw new Error('The assistant returned an unreadable response.');for(const suggestion of result.suggestions.slice(0,3)){const article=document.createElement('article');article.className='suggestion';const title=document.createElement('h3');title.textContent=String(suggestion.title||'Design direction');const rationale=document.createElement('p');rationale.textContent=String(suggestion.reason||'');const list=document.createElement('ol');for(const step of (suggestion.steps||[]).slice(0,5)){const li=document.createElement('li');li.textContent=String(step);list.append(li);}article.append(title,rationale,list);if(['section','columns','grid'].includes(suggestion.block)){const button=document.createElement('button');button.textContent='Add an empty '+({section:'section',columns:'two-column container',grid:'three-column container'}[suggestion.block]);button.addEventListener('click',()=>{insertBlock(suggestion.block,editor.getWrapper());toast('Empty structure added. Add your own content and style.');});article.append(button);}area.append(article);}}
addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
showStart();const params=new URLSearchParams(location.search);let intro={};try{intro=JSON.parse(sessionStorage.getItem('oakline-start')||'{}');sessionStorage.removeItem('oakline-start');}catch{}$('start-name').value=String(intro.name||params.get('brand')||'').slice(0,80);$('start-brief').value=String(intro.brief||params.get('brief')||'').slice(0,4000);if((intro.mode||params.get('mode'))==='existing'){document.querySelector('[name="project-kind"][value="existing"]').checked=true;updateStartMode();}checkAI();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};register({name:'read_website_design',description:'Read the current Oakline project brief, website name and page outline.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>{const doc=new DOMParser().parseFromString(editor.getHtml(),'text/html');return{content:[{type:'text',text:JSON.stringify({name:meta.name,brief:meta.brief,outline:doc.body.textContent.slice(0,6000)})}]};}});register({name:'add_website_element',description:'Add an editable building block to the current Oakline website after the user has started a project.',inputSchema:{type:'object',properties:{element:{type:'string',enum:blocks.map(b=>b.id)}},required:['element'],additionalProperties:false},execute:async input=>{if(!started||!input||Object.keys(input).some(key=>key!=='element')||!blocks.some(b=>b.id===input.element)||input.element==='image')return{isError:true,content:[{type:'text',text:'Start a project and choose a supported element. Upload images through the image control.'}]};insertBlock(input.element,editor.getWrapper());await new Promise(resolve=>requestAnimationFrame(resolve));return{content:[{type:'text',text:'Element added to your canvas.'}]};}});}
